import{_ as l,l as i,o as e,c as s,v as r,p as n,x as t,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"C10K 与并发模型","description":"","frontmatter":{"title":"C10K 与并发模型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/c10k-concurrency.md","filePath":"cs/c10k-concurrency.md","lastUpdated":1789023840000}'),h={name:"cs/c10k-concurrency.md"};function E(_,a,f,u,m,C){const o=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="c10k-与并发模型" tabindex="-1">C10K 与并发模型 <a class="header-anchor" href="#c10k-与并发模型" aria-label="Permalink to &quot;C10K 与并发模型&quot;">​</a></h1><div class="epigraph"><p>一万并发连接的瓶颈在每连接的内核与用户态开销；事件驱动、高效多路复用与少拷贝把 C10K 变成 C10M 量级的工程，而不是新协议。</p><footer>—— 据 Kegel, The C10K Problem；libevent/nginx 实践整理</footer></div><p><a href="/cs/reactor-proactor">Reactor</a> 给模式。<a href="/cs/socket-api">套接字</a> 给 API。<a href="/cs/reactor-proactor">上一课</a> 留下规模。缺口是 <strong>C10K 问题</strong>：fd 上限、epoll vs select、内存。本课不把粘包写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2000 年代：select 线性扫描、每连接一进程、内核套接字缓冲默认大，一万连接吃光 RAM。对策：epoll/kqueue、降低缓冲、事件循环、零拷贝 sendfile。今日 C10M 还要网卡多队列、RPS、用户态栈。这与 \\(C\\) 公式无关，是主机实现税。Maglev 把连接摊到多机，是水平解。</p><p>不要把 C10K 写成必须用某种语言。</p><p><span class="marginnote">Kegel C10K。本课不点名基准广告。</span></p><h3 id="每连接开销-×-n" tabindex="-1">每连接开销 × N <a class="header-anchor" href="#每连接开销-×-n" aria-label="Permalink to &quot;每连接开销 × N&quot;">​</a></h3><p>事件化与少拷贝，不是新协议。H2 多流也减连接数。fd 耗尽是可用性攻击面。业务同步塞进循环会更早失败。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：进程 / 线程 / 事件 / 协程。画：连接数 × 每连接开销。与 incast：那是网络队列；这里是主机 fd。</p>',11)),(e(),n(p,null,{default:t(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E8%BF%9E%E6%8E%A5%E6%95%B0%22%5D%20--%3E%20COST%5B%22%E6%AF%8F%E8%BF%9E%E6%8E%A5%E5%86%85%E5%AD%98%E4%B8%8E%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%0A%20%20COST%20--%3E%20LIM%5B%22CPU%2FRAM%20%E4%B8%8A%E9%99%90%22%5D%0A%20%20EV%5B%22%E4%BA%8B%E4%BB%B6%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20LOW%5B%22%E9%99%8D%E6%AF%8F%E8%BF%9E%E6%8E%A5%E5%BC%80%E9%94%80%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HTTP 持久减少握手但仍占 fd。H2 多流在一条连接上减轻 C10K。QUIC 用户态更灵活也更吃 CPU。SYN cookies 保护握手，不降低已建立连接数。测量：ss -s，不是 ping。</p><p>安全：fd 耗尽是拒绝服务，要 ulimit 与限连。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 DPDK 的全部。粘包与帧定界是下一课。后课默认：万级并发靠事件化与减每连接状态。</p><p>把业务逻辑同步塞进事件循环会在远低于 C10K 时失败。</p><p>上一课留下的缺口在本课收口；「C10K 与并发模型」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/message-framing">粘包与帧定界</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>瓶颈是每连接开销 × N。</li><li>高效多路复用 + 少线程。</li><li>协议多路（H2）也减连接数。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Kegel C10K；服务器实践。</li></ul>',10))])}const k=l(h,[["render",E]]);export{A as __pageData,k as default};
